    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  await page.setViewport({ width: 1200, height: 2000, deviceScaleFactor: 2 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Get actual content height
  const bodyHeight = await page.evaluate(() => document.querySelector('.poster').offsetHeight);

  await page.setViewport({ width: 1200, height: bodyHeight, deviceScaleFactor: 2 });

  // Wait a moment for re-render
  await new Promise(r => setTimeout(r, 500));

  const element = await page.$('.poster');
  await element.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png'
  });

  console.log(`Screenshot saved. Dimensions: 1200x${bodyHeight} @2x`);
  await browser.close();
})();

